def load(p):
    return json.loads(pathlib.Path(p).read_text())

def diffs(verdict_path):
    d=load(verdict_path)
    base=d['medians']['base']
    out={}
    for variant, vals in d['medians'].items():
        if variant=='base' or not variant.startswith('muse-'):
            continue
        rows=[]
        for setting in ["1x128","8x128","32x128","32x1024"]:
            row=[]
            for phase in ["decode","prompt","request"]:
                diff=vals[setting][phase]['median']-base[setting][phase]['median']
                row.append(round(diff,2))
            rows.append(row)
        out[variant]=rows
    return out, d

for name,path in [("ready-1","muse-spark/round-4/checks/ready-1/ready-verdict.json"),("ready-2","muse-spark/round-4/checks/ready-2/ready-verdict.json")]:
    out,d = diffs(path)
    print(name, "pass=",d['pass'], "variants pass:", {k:v['pass'] for k,v in d['variants'].items()})
    print(" attempts:", d['protocol']['attempts'])
    for variant, rows in out.items():
        # rows per setting: decode,prompt,request
        dec=[r[0] for r in rows]; pr=[r[1] for r in rows]; req=[r[2] for r in rows]
        print(f" {variant} decode {dec} prompt {pr} request {req}")

# Also check round totals recount
